/**
 * Intro copy and one sample item per category for /categories/[slug]
 * (F-CAT, ARCHITECTURE §5.3). The intro comes from
 * content/category-pages/<slug>.json once CAT-1 writes it. The sample
 * is the category's easiest active multiple-choice item by predicted p,
 * ties to the lower id, so it changes only when the bank does.
 *
 * Generated by `npm run content:build` from content/category-pages/ and content/practice/. Do not edit:
 * CI rebuilds it and fails on any difference (ARCHITECTURE §5.3).
 */
export interface CategoryPageSample {
  readonly id: string;
  readonly format: "mc" | "tf" | "comparison";
  readonly stem: string;
  readonly options: readonly string[];
  readonly correct: number;
  readonly explanation: string;
  readonly learnMore: string;
}

export interface CategoryPage {
  readonly slug: string;
  readonly intro: string | null;
  readonly sample: CategoryPageSample | null;
}

